#!/usr/bin/env node
// Builds the chat pack: adapters/chat-pack/files/, the files a person uploads to a chat app's project (ChatGPT
// Projects, Gemini Gems, Grok, DeepSeek). Chat apps keep only a file's name, not its folder, so every skill's SKILL.md
// would arrive as "SKILL.md" and overwrite the one before. Here each skill becomes <skill>.md, and a file a skill
// needs next to it gets the skill's name in front (html-report's skeleton.html is html-report-skeleton.html).
// Node only, no dependencies, no network. Deterministic: the same sources always give the same files.
//
// Usage
//   node .github/scripts/chat-pack.mjs           build, write what changed, remove files no longer built
//   node .github/scripts/chat-pack.mjs --check   build in memory only; exit 1 when the folder is stale or names clash
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const OUT = path.join(REPO, "adapters", "chat-pack", "files");
// rich-report needs Claude Artifacts, which no chat app here has; html-report covers the same requests.
const SKIP = new Set(["rich-report"]);
// Files a skill reads from its own folder that a chat app needs too: skill -> [file]
const EXTRA = { "html-report": ["skeleton.html"] };

const norm = (s) => s.replace(/^﻿/, "").replace(/\r\n?/g, "\n");
const read = (p) => norm(fs.readFileSync(p, "utf8"));
const rel = (p) => path.relative(REPO, p).split(path.sep).join("/");

export function build() {
  const files = new Map(); // name in the pack -> content
  const add = (name, text) => {
    const clash = [...files.keys()].find((n) => n.toLowerCase() === name.toLowerCase());
    if (clash) throw new Error(`two files would be named ${name} in the chat pack (${clash})`);
    files.set(name, text);
  };
  add("ROUTING.md", read(path.join(REPO, "ROUTING.md")));
  const skills = fs.readdirSync(path.join(REPO, "skills"), { withFileTypes: true })
    .filter((d) => d.isDirectory() && !SKIP.has(d.name)).map((d) => d.name).sort();
  for (const skill of skills) {
    const src = path.join(REPO, "skills", skill, "SKILL.md");
    if (!fs.existsSync(src)) continue;
    const extras = (EXTRA[skill] || []).map((f) => [f, `${skill}-${f}`]);
    const note = [
      `<!-- makkov-harness chat pack: the ${skill} skill, from ${rel(src)}. Generated by .github/scripts/chat-pack.mjs; edit the source, not this copy.`,
      ...extras.map(([f, as]) => `     In this pack, the file this skill calls ${f} is the attached file ${as}.`),
      "     Other files this skill names in its own folder are not in the chat pack; work without them. -->",
    ].join("\n");
    add(`${skill}.md`, `${note}\n${read(src)}`);
    for (const [f, as] of extras) add(as, read(path.join(REPO, "skills", skill, f)));
  }
  return files;
}

function main() {
  const check = process.argv.includes("--check");
  let files;
  try { files = build(); } catch (e) { console.error(`chat-pack: ${e.message}`); process.exit(1); }
  const existing = fs.existsSync(OUT) ? fs.readdirSync(OUT).filter((f) => fs.statSync(path.join(OUT, f)).isFile()) : [];
  const stale = [...files].filter(([name, text]) => !existing.includes(name) || read(path.join(OUT, name)) !== text).map(([n]) => n);
  const extra = existing.filter((f) => !files.has(f));
  if (check) {
    if (stale.length || extra.length) {
      console.error(`chat-pack --check: ${rel(OUT)} is out of date (${[...stale.map((n) => `stale ${n}`), ...extra.map((n) => `not built: ${n}`)].join(", ")}). Run: node .github/scripts/chat-pack.mjs`);
      process.exit(1);
    }
    console.log(`chat-pack --check: up to date (${files.size} files, every name unique).`);
    return;
  }
  fs.mkdirSync(OUT, { recursive: true });
  for (const name of stale) fs.writeFileSync(path.join(OUT, name), files.get(name), "utf8");
  for (const name of extra) fs.rmSync(path.join(OUT, name));
  console.log(`chat-pack: ${files.size} files in ${rel(OUT)} (${stale.length} written, ${extra.length} removed).`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) main();
